// Ported near-verbatim from the original site's `Component extends DCLogic`
// runtime (support.js) so every scroll/hover/pin effect keeps behaving
// exactly as it did in the static .dc.html build.
export function initHome(root) {
  const $ = (s, c) => Array.from((c || root).querySelectorAll(s));
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const cleanup = [];
  const on = (t, e, f, o) => { t.addEventListener(e, f, o); cleanup.push(() => t.removeEventListener(e, f, o)); };
  const state = {};
  let lang = "pt";

  /* ---- responsive columns (no stylesheet) ---- */
  const heroGrid = root.querySelector("#heroGrid");
  const navlinks = root.querySelector("#navlinks");
  const layout = () => {
    const w = window.innerWidth, wide = w >= 900, mid = w >= 700;
    if (heroGrid) heroGrid.style.gridTemplateColumns = wide ? "minmax(0,1.05fr) minmax(0,.95fr)" : "minmax(0,1fr)";
    const artWrap = root.querySelector("#heroArtWrap");
    if (artWrap) artWrap.style.display = wide ? "flex" : "none";
    const heroTagMobile = root.querySelector("#heroTagMobile");
    if (heroTagMobile) heroTagMobile.style.display = wide ? "none" : "block";
    if (navlinks) navlinks.style.display = w >= 1080 ? "flex" : "none";
    const langBtn = root.querySelector("#lang");
    if (langBtn) langBtn.style.display = w < 640 ? "none" : "inline-block";
    const ctaNav = root.querySelector("#ctaNav");
    if (ctaNav) ctaNav.style.display = w < 640 ? "none" : "inline-block";
    const menuBtn = root.querySelector("#menuBtn");
    if (menuBtn) menuBtn.style.display = w >= 1080 ? "none" : "flex";
    if (w >= 1080 && state.closeMobileMenu) state.closeMobileMenu();
    if (state.svcMode) state.svcMode(wide);
    $("[data-cols]").forEach(e => e.style.gridTemplateColumns = wide ? e.dataset.cols : "1fr");
    $("[data-cols2]").forEach(e => e.style.gridTemplateColumns = mid ? e.dataset.cols2 : "1fr");
    $("[data-cols3]").forEach(e => e.style.gridTemplateColumns = wide ? e.dataset.cols3 : "repeat(2,1fr)");
    $("[data-cols4]").forEach(e => e.style.gridTemplateColumns = wide ? e.dataset.cols4 : "1fr");
    const procWide = w >= 1080;
    $("[data-cols5]").forEach(e => e.style.gridTemplateColumns = procWide ? e.dataset.cols5 : "1fr");
    const procSide = root.querySelector("#procSide");
    if (procSide) procSide.style.display = procWide ? "block" : "none";
  };
  layout(); on(window, "resize", layout);
  setTimeout(layout, 250);
  setTimeout(layout, 900);

  /* ---- hero line entrance ---- */
  const heroInners = $("[data-hero-inner]");
  const showHero = () => heroInners.forEach(el => { el.style.transform = "translateY(0)"; });
  if (!reduce) {
    heroInners.forEach((el, i) => {
      el.style.transform = "translateY(105%)";
      el.style.transition = "transform 1.15s cubic-bezier(.16,1,.3,1) " + (i * 0.11 + 0.1) + "s";
    });
    setTimeout(showHero, 60);
    setTimeout(showHero, 900);
  }

  /* ---- scroll reveals — visibility never depends on an observer ---- */
  const revealables = $("[data-reveal]");
  const showReveal = (el) => {
    if (el._shown) return;
    el._shown = true;
    const sibs = Array.from(el.parentElement ? el.parentElement.children : []).filter(n => n.hasAttribute && n.hasAttribute("data-reveal"));
    el.style.transitionDelay = Math.min(Math.max(0, sibs.indexOf(el)) * 0.085, 0.5) + "s";
    el.style.opacity = "1";
    el.style.transform = el.dataset.reveal === "line" ? "scaleX(1)" : "translateY(0)";
  };
  const counters = $("[data-count]");
  const runCount = (el) => {
    if (el._shown) return;
    el._shown = true;
    const target = parseFloat(el.dataset.count) || 0;
    const pre = el.dataset.prefix || "", suf = el.dataset.suffix || "";
    const t0 = Date.now(), dur = 1400;
    const tick = () => {
      const p = Math.min(1, (Date.now() - t0) / dur), e = 1 - Math.pow(1 - p, 3);
      el.textContent = pre + Math.round(target * e) + suf;
      if (p < 1) setTimeout(tick, 32);
    };
    tick();
  };

  if (!reduce) {
    revealables.forEach(el => {
      el.style.opacity = "0";
      el.style.willChange = "opacity, transform";
      if (el.dataset.reveal === "line") { el.style.transform = "scaleX(0)"; el.style.transformOrigin = "left"; }
      else el.style.transform = "translateY(26px)";
      el.style.transition = "opacity .95s cubic-bezier(.16,1,.3,1), transform 1.05s cubic-bezier(.16,1,.3,1)";
    });
  } else {
    revealables.forEach(showReveal);
  }

  const inView = (el) => {
    const r = el.getBoundingClientRect();
    const h = window.innerHeight || 800;
    return r.top < h * 0.94 && r.bottom > -80;
  };
  const extra = [];
  /* ---- Sobre plate: shrink on scroll, then pin until the section ends ---- */
  const sobrePlate = root.querySelector("#sobrePlate");
  const sobreRail = root.querySelector("#sobreRail");
  const sobreSection = root.querySelector("#sobre");
  if (sobrePlate && sobreRail && sobreSection && !reduce) {
    const TOP = 104;
    const S0 = 1.24, S1 = 0.96;
    sobreRail.style.position = "sticky";
    sobreRail.style.top = TOP + "px";
    sobrePlate.style.transformOrigin = "center top";
    const updateSobre = () => {
      const narrow = window.innerWidth < 900;
      if (narrow) {
        sobreRail.style.position = "relative";
        sobreRail.style.top = "";
        sobrePlate.style.scale = "1";
        return;
      }
      sobreRail.style.position = "sticky";
      sobreRail.style.top = TOP + "px";
      const railR = sobreRail.getBoundingClientRect();
      const h = window.innerHeight || 800;
      const start = h * 0.88;
      const p = Math.min(1, Math.max(0, (start - railR.top) / (start - TOP)));
      const s = S0 - p * (S0 - S1);
      sobrePlate.style.scale = s.toFixed(3);
    };
    extra.push(updateSobre);
    updateSobre();
    on(window, "resize", updateSobre);
  }

  const sweep = () => {
    revealables.forEach(el => { if (!el._shown && inView(el)) showReveal(el); });
    counters.forEach(el => { if (!el._shown && inView(el)) runCount(el); });
    for (let i = 0; i < extra.length; i++) extra[i]();
  };
  setTimeout(sweep, 80);
  const poll = setInterval(sweep, 220);
  cleanup.push(() => clearInterval(poll));
  const bail = setTimeout(() => {
    if (!revealables.some(el => el._shown)) { revealables.forEach(showReveal); counters.forEach(runCount); }
    showHero();
  }, 4000);
  cleanup.push(() => clearTimeout(bail));

  /* ---- nav + progress + hero parallax ---- */
  const nav = root.querySelector("#nav");
  const prog = root.querySelector("#prog");
  const heroArt = root.querySelector("#heroArt");
  let scroller = null;
  for (let n = root.querySelector && root.querySelector("#top") ? root.querySelector("#top").parentElement : null; n && n !== document.body; n = n.parentElement) {
    const ov = getComputedStyle(n).overflowY;
    if ((ov === "auto" || ov === "scroll") && n.scrollHeight > n.clientHeight + 4) { scroller = n; break; }
  }
  const scrollY = () => scroller ? scroller.scrollTop : (window.scrollY || document.documentElement.scrollTop || 0);
  const scrollMax = () => scroller
    ? scroller.scrollHeight - scroller.clientHeight
    : (document.documentElement.scrollHeight - window.innerHeight);
  const onScroll = () => {
    const y = scrollY();
    const max = scrollMax();
    if (prog) prog.style.width = (max > 0 ? (y / max) * 100 : 0) + "%";
    if (nav) {
      const solid = y > 60;
      nav.style.backgroundColor = solid ? "rgba(243,242,242,.72)" : "rgba(243,242,242,.42)";
      nav.style.borderBottomColor = solid ? "rgba(32,31,29,.14)" : "rgba(32,31,29,.08)";
      nav.style.padding = solid ? "12px clamp(20px,5vw,64px)" : "18px clamp(20px,5vw,64px)";
    }
    if (heroArt && !reduce && y < window.innerHeight * 1.2) {
      heroArt.style.setProperty("--scrollY", (y * -0.07) + "px");
      heroArt.style.setProperty("--scrollS", (1 + y * 0.00008).toFixed(4));
      if (heroArt._applyTilt) heroArt._applyTilt();
    }
  };
  extra.push(onScroll);
  on(window, "scroll", onScroll, { passive: true });
  if (scroller) on(scroller, "scroll", onScroll, { passive: true });
  on(window, "scroll", sweep, { passive: true });
  if (scroller) on(scroller, "scroll", sweep, { passive: true });
  onScroll();

  /* ---- hero mouse parallax (background drift) ---- */
  if (!reduce && window.matchMedia("(pointer:fine)").matches) {
    const slot = heroArt ? heroArt.querySelector("img") : null;
    on(window, "mousemove", (e) => {
      const dx = (e.clientX / window.innerWidth - 0.5), dy = (e.clientY / window.innerHeight - 0.5);
      if (slot) slot.style.transform = "translate3d(" + (dx * -16) + "px," + (dy * -16) + "px,0) scale(1.06)";
    }, { passive: true });
    if (slot) { slot.style.transition = "transform .9s cubic-bezier(.16,1,.3,1)"; slot.style.transform = "scale(1.06)"; }
  }

  /* ---- hero card: floating tilt + shine on hover ---- */
  if (heroArt && !reduce && window.matchMedia("(pointer:fine)").matches) {
    const shine = root.querySelector("#heroShine");
    const glow = root.querySelector("#heroGlow");
    const glint = root.querySelector("#heroBorderGlint");
    let floatT = 0, hovering = false, glintT = 0;
    const setGlintPos = (r) => {
      if (!glint) return;
      const w = r.width, h = r.height, per = 2 * (w + h);
      const d = (glintT % 1) * per;
      let x, y, rot;
      if (d < w) { x = d; y = 0; rot = 0; }
      else if (d < w + h) { x = w; y = d - w; rot = 90; }
      else if (d < 2 * w + h) { x = w - (d - w - h); y = h; rot = 180; }
      else { x = 0; y = h - (d - 2 * w - h); rot = 270; }
      glint.style.transform = "translate(" + x + "px," + y + "px) rotate(" + rot + "deg)";
    };
    const floatLoop = () => {
      floatT += 0.005;
      glintT += 0.00055;
      if (!hovering) {
        heroArt.style.setProperty("--fy", Math.sin(floatT) * 8 + "px");
        applyTransform();
      }
      setGlintPos(heroArt.getBoundingClientRect());
    };
    heroArt.style.setProperty("--fy", "0px");
    heroArt.style.setProperty("--rx", "0deg");
    heroArt.style.setProperty("--ry", "0deg");
    heroArt.style.setProperty("--scrollY", "0px");
    heroArt.style.setProperty("--scrollS", "1");
    const applyTransform = () => {
      heroArt.style.transform = "translate3d(0,var(--scrollY),0) scale(var(--scrollS)) perspective(900px) translateY(var(--fy)) rotateX(var(--rx)) rotateY(var(--ry)) " + (hovering ? "scale(1.02)" : "scale(1)");
    };
    heroArt._applyTilt = applyTransform;
    const floatTimer = setInterval(floatLoop, 16);
    cleanup.push(() => clearInterval(floatTimer));
    on(heroArt, "mouseenter", () => {
      hovering = true;
      heroArt.style.transition = "transform .15s ease-out";
      if (shine) { shine.style.transition = "opacity .3s ease"; shine.style.opacity = "1"; }
      if (glow) { glow.style.transition = "opacity .3s ease"; glow.style.opacity = "1"; }
    });
    on(heroArt, "mousemove", (e) => {
      const r = heroArt.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
      heroArt.style.setProperty("--rx", ((0.5 - py) * 14).toFixed(2) + "deg");
      heroArt.style.setProperty("--ry", ((px - 0.5) * 14).toFixed(2) + "deg");
      if (shine) shine.style.background = "radial-gradient(circle at " + (px * 100) + "% " + (py * 100) + "%, rgba(255,255,255,.6), rgba(255,255,255,0) 45%)";
      applyTransform();
    }, { passive: true });
    on(heroArt, "mouseleave", () => {
      hovering = false;
      heroArt.style.transition = "transform .6s cubic-bezier(.2,.8,.2,1)";
      heroArt.style.setProperty("--rx", "0deg");
      heroArt.style.setProperty("--ry", "0deg");
      applyTransform();
      if (shine) { shine.style.transition = "opacity 1.6s ease"; shine.style.opacity = "0"; }
      if (glow) { glow.style.transition = "opacity 1.6s ease"; glow.style.opacity = "0"; }
    });
  }

  /* ---- services: pinned stage, dissolve images, rolling text ---- */
  const svcTrack = root.querySelector("#svcTrack");
  const svcPin = root.querySelector("#svcPin");
  const svcGrid = root.querySelector("#svcPinGrid");
  const svcStage = root.querySelector("#svcTextStage");
  const svcImgStage = root.querySelector("#svcImgStage");
  const svcNav = root.querySelector("#svcNav");
  const svcBar = root.querySelector("#svcBar");
  const svcTexts = $("[data-svctext]");
  const svcImgs = $("[data-svcimg]");
  const svcNums = $("[data-svcgo]");
  let svcIdx = 0, svcPinned = true;

  const setSvc = (i) => {
    if (i === svcIdx) return;
    svcIdx = i;
    svcTexts.forEach((t, k) => {
      const d = k - i;
      t.style.opacity = d === 0 ? "1" : "0";
      t.style.transform = "translateY(" + (d === 0 ? 0 : d < 0 ? -64 : 64) + "px)";
      t.style.pointerEvents = d === 0 ? "auto" : "none";
    });
    svcImgs.forEach((im, k) => { im.style.opacity = k === i ? "1" : "0"; });
    svcNums.forEach((n, k) => { n.style.color = k === i ? "var(--color-accent-400)" : "var(--color-neutral-600)"; });
  };

  const updateSvc = () => {
    if (!svcPinned || !svcTrack) return;
    const r = svcTrack.getBoundingClientRect();
    const total = r.height - (window.innerHeight || 800);
    const p = Math.min(1, Math.max(0, -r.top / (total || 1)));
    if (svcBar) svcBar.style.height = (p * 100).toFixed(1) + "%";
    setSvc(Math.min(3, Math.floor(p * 4 + 0.001)));
  };
  if (svcTrack) { extra.push(updateSvc); updateSvc(); }

  svcNums.forEach((n, k) => on(n, "click", () => {
    if (!svcTrack) return;
    const r = svcTrack.getBoundingClientRect();
    const total = r.height - (window.innerHeight || 800);
    const target = (window.scrollY || 0) + r.top + ((k + 0.5) / 4) * total;
    window.scrollTo({ top: target, behavior: "smooth" });
  }));

  /* ---- services card: mouse tilt only (no shine/glow) ---- */
  if (svcImgStage && !reduce && window.matchMedia("(pointer:fine)").matches) {
    svcImgStage.style.transformStyle = "preserve-3d";
    svcImgStage.style.transition = "transform .6s cubic-bezier(.2,.8,.2,1)";
    on(svcImgStage, "mouseenter", () => { svcImgStage.style.transition = "transform .15s ease-out"; });
    on(svcImgStage, "mousemove", (e) => {
      const r = svcImgStage.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
      svcImgStage.style.transform = "perspective(900px) rotateX(" + ((0.5 - py) * 12).toFixed(2) + "deg) rotateY(" + ((px - 0.5) * 12).toFixed(2) + "deg) scale(1.015)";
    }, { passive: true });
    on(svcImgStage, "mouseleave", () => {
      svcImgStage.style.transition = "transform .7s cubic-bezier(.2,.8,.2,1)";
      svcImgStage.style.transform = "perspective(900px) rotateX(0deg) rotateY(0deg) scale(1)";
    });
  }

  const sizeSvcStage = () => {
    if (!svcStage || !svcPinned) return;
    const prev = svcTexts.map(t => ({ pos: t.style.position, op: t.style.opacity, tr: t.style.transform }));
    let tallest = 0;
    svcTexts.forEach(t => {
      t.style.position = "relative";
      t.style.opacity = "0";
      t.style.transform = "none";
      tallest = Math.max(tallest, t.offsetHeight);
    });
    svcTexts.forEach((t, k) => { t.style.position = prev[k].pos; t.style.opacity = prev[k].op; t.style.transform = prev[k].tr; });

    const vh = window.innerHeight || 800;
    if (svcPin) svcPin.style.padding = vh < 720
      ? "72px 0 26px"
      : "clamp(86px,11vh,120px) 0 clamp(40px,6vh,72px)";
    const avail = svcGrid ? svcGrid.clientHeight : vh;
    const target = Math.min(tallest + 8, Math.max(200, avail));
    svcStage.style.minHeight = target + "px";
    const factor = tallest > 0 ? Math.min(1, (target - 8) / tallest) : 1;
    svcTexts.forEach(t => {
      t.style.transformOrigin = "left top";
      t.style.scale = factor < 0.999 ? factor.toFixed(3) : "1";
    });
  };

  state.svcMode = (wide) => {
    svcPinned = wide && !reduce;
    if (!svcTrack || !svcPin) return;
    if (svcPinned) {
      svcTrack.style.height = "400vh";
      svcPin.style.position = "sticky";
      svcPin.style.height = "100vh";
      if (svcGrid) svcGrid.style.gridTemplateColumns = "auto 1.1fr .9fr";
      if (svcNav) svcNav.style.display = "flex";
      if (svcImgStage) { svcImgStage.style.display = "block"; svcImgStage.style.height = "100%"; }
      if (svcStage) { svcStage.style.position = "relative"; svcStage.style.overflow = "hidden"; }
      svcTexts.forEach((t, k) => {
        t.style.position = "absolute";
        t.style.opacity = k === svcIdx ? "1" : "0";
        t.style.transform = "translateY(" + (k === svcIdx ? 0 : k < svcIdx ? -64 : 64) + "px)";
      });
      setTimeout(sizeSvcStage, 30);
      setTimeout(sizeSvcStage, 600);
    } else {
      svcTrack.style.height = "auto";
      svcPin.style.position = "static";
      svcPin.style.height = "auto";
      if (svcGrid) svcGrid.style.gridTemplateColumns = "1fr";
      if (svcNav) svcNav.style.display = "none";
      if (svcImgStage) svcImgStage.style.display = "none";
      if (svcStage) { svcStage.style.position = "static"; svcStage.style.overflow = "visible"; svcStage.style.minHeight = "0"; }
      svcTexts.forEach(t => {
        t.style.position = "relative";
        t.style.opacity = "1";
        t.style.transform = "none";
        t.style.pointerEvents = "auto";
        t.style.paddingTop = "34px";
        t.style.marginTop = "34px";
        t.style.borderTop = "1px solid rgba(243,242,242,.18)";
      });
    }
  };
  state.svcMode(window.innerWidth >= 900);

  /* ---- hero roles: hide separators that fall at a line end ---- */
  const roleDots = $("[data-roledot]");
  if (roleDots.length) {
    const trimRoleDots = () => {
      roleDots.forEach(d => { d.style.display = "block"; });
      roleDots.forEach(d => {
        const next = d.nextElementSibling;
        if (!next) { d.style.display = "none"; return; }
        if (next.getBoundingClientRect().top > d.getBoundingClientRect().top + 2) d.style.display = "none";
      });
    };
    setTimeout(trimRoleDots, 60);
    setTimeout(trimRoleDots, 700);
    on(window, "resize", trimRoleDots);
  }

  /* ---- process: gold line grows through the timeline as you scroll, nodes light up as it passes ---- */
  const procTrack = root.querySelector("#procTrack");
  const procLineFill = root.querySelector("#procLineFill");
  const procSteps = $("[data-step]", procTrack || root);
  const setStepLit = (el, lit) => {
    const num = el.querySelector("[data-stepnum]");
    const body = el.querySelector("[data-stepbody]");
    if (num) {
      num.style.color = lit ? "var(--color-bg)" : "rgba(32,31,29,.4)";
      num.style.borderColor = lit ? "var(--color-accent)" : "rgba(32,31,29,.2)";
      num.style.backgroundColor = lit ? "var(--color-accent)" : "var(--color-bg)";
      num.style.transform = lit ? "scale(1.08)" : "scale(1)";
    }
    if (body) body.style.transform = lit ? "translateX(6px)" : "translateX(0)";
  };
  procSteps.forEach(el => setStepLit(el, false));
  const procSideNum = root.querySelector("#procSideNum");
  const procSideTitle = root.querySelector("#procSideTitle");
  const procSideDesc = root.querySelector("#procSideDesc");
  const procBenefits = {
    pt: [
      "Clareza total antes de qualquer decisão.",
      "Cada conteúdo com propósito de venda.",
      "Direção de cena que transmite confiança.",
      "Ritmo e identidade em cada entrega.",
      "Decisões guiadas por dado, não achismo.",
    ],
    en: [
      "Total clarity before any decision.",
      "Every piece of content with a sales purpose.",
      "Scene direction that builds trust.",
      "Pace and identity in every delivery.",
      "Decisions guided by data, not guesswork.",
    ],
  };
  let procSideIdx = -1;
  if (procTrack && procSteps.length) {
    const updateProc = () => {
      const r = procTrack.getBoundingClientRect();
      const h = window.innerHeight || 800;
      const start = h * 0.82, end = h * 0.32;
      const raw = (start - r.top) / (r.height + (start - end));
      const pct = Math.min(1, Math.max(0, raw));
      if (procLineFill) procLineFill.style.height = (pct * 100).toFixed(1) + "%";
      procSteps.forEach((el, i) => {
        const threshold = i / procSteps.length;
        setStepLit(el, pct >= threshold + 0.02);
      });
      const idx = Math.min(procSteps.length - 1, Math.floor(pct * procSteps.length + 0.001));
      if (idx !== procSideIdx && procSideNum) {
        procSideIdx = idx;
        const step = procSteps[idx];
        procSideNum.textContent = String(idx + 1).padStart(2, "0");
        if (procSideTitle) procSideTitle.textContent = step.querySelector("h3").textContent;
        if (procSideDesc) procSideDesc.textContent = procBenefits[lang][idx];
        [procSideNum, procSideTitle, procSideDesc].forEach(el => {
          if (!el) return;
          el.style.opacity = "0";
          requestAnimationFrame(() => { el.style.opacity = "1"; });
        });
      }
    };
    extra.push(updateProc);
    updateProc();
  }

  /* ---- plan cards: lift + gold list marks ---- */
  $("[data-plan] li").forEach(li => {
    const dot = document.createElement("span");
    dot.style.cssText = "position:absolute;left:0;top:.62em;width:5px;height:1px;background:var(--color-accent)";
    li.insertBefore(dot, li.firstChild);
  });
  $("[data-plan][data-featured]").forEach(el => {
    el.style.position = "relative";
    const band = document.createElement("span");
    band.style.cssText = "position:absolute;left:-1px;right:-1px;top:-1px;height:3px;background:var(--color-accent)";
    el.insertBefore(band, el.firstChild);
    [["left:-1px;bottom:-1px", "border-left:1px solid var(--color-accent);border-bottom:1px solid var(--color-accent)"],
     ["right:-1px;bottom:-1px", "border-right:1px solid var(--color-accent);border-bottom:1px solid var(--color-accent)"]].forEach(([pos, br]) => {
      const c = document.createElement("span");
      c.style.cssText = "position:absolute;" + pos + ";width:22px;height:22px;" + br + ";pointer-events:none";
      el.appendChild(c);
    });
    const price = el.querySelector("span[style*='clamp(42px']");
    if (price) price.style.color = "var(--color-accent-700)";
    const sub = el.querySelector("p[style*='italic']");
    if (sub) sub.style.color = "var(--color-accent-700)";
  });

  /* ---- side plans emerge from behind the centre card on scroll ---- */
  const fanCards = [];
  $("[data-panel]").forEach(p => {
    const cards = Array.from(p.querySelectorAll("[data-plan]"));
    if (cards.length !== 3) return;
    const mid = cards[Math.floor((cards.length - 1) / 2)];
    const feat = cards.find(c => c.hasAttribute("data-featured"));
    const origin = (feat && Math.abs(cards.indexOf(feat) - cards.indexOf(mid)) <= 1) ? feat : mid;
    cards.forEach(c => {
      c.style.willChange = "transform, opacity";
      c.style.zIndex = c === origin ? "3" : "1";
      if (c !== origin) { c.style.transition = "none"; fanCards.push({ el: c, panel: p, centre: origin }); }
    });
  });
  const panelEligible = (panel) => {
    if (!panel || !panel.offsetParent) return false;
    const cards = Array.from(panel.querySelectorAll("[data-plan]"));
    if (cards.length !== 3) return false;
    const t = cards[0].offsetTop;
    return cards.every(c => Math.abs(c.offsetTop - t) < 4);
  };
  const measureFan = (c) => {
    c._dx = (c.centre.offsetLeft + c.centre.offsetWidth / 2) - (c.el.offsetLeft + c.el.offsetWidth / 2);
    c._dy = (c.centre.offsetTop + c.centre.offsetHeight / 2) - (c.el.offsetTop + c.el.offsetHeight / 2);
  };
  const fanRest = new WeakMap();
  if (fanCards.length && !reduce) {
    const groups = new Map();
    fanCards.forEach(c => {
      if (!groups.has(c.panel)) groups.set(c.panel, []);
      groups.get(c.panel).push(c);
    });
    const updateFan = () => {
      groups.forEach((cards, panel) => {
        if (!panelEligible(panel)) {
          cards.forEach(c => { fanRest.set(c.el, null); c.el.style.opacity = "1"; if (!c.el._hovering) c.el.style.transform = c.el._baseRest || ""; });
          return;
        }
        const r = panel.getBoundingClientRect();
        const h = window.innerHeight || 800;
        const start = h * 0.92, end = h * 0.34;
        const p = Math.min(1, Math.max(0, (start - r.top) / (start - end)));
        const e = 1 - Math.pow(1 - p, 3);
        cards.forEach(c => {
          if (c._dx == null || (!c._dx && !c._dy)) measureFan(c);
          const dx = (c._dx || 0) * (1 - e), dy = (c._dy || 0) * (1 - e);
          const t = "translate(" + dx.toFixed(1) + "px," + dy.toFixed(1) + "px) scale(" + (0.86 + e * 0.14).toFixed(3) + ")";
          fanRest.set(c.el, t);
          if (!c.el._hovering) c.el.style.transform = t;
          c.el.style.opacity = (0.12 + e * 0.88).toFixed(3);
        });
      });
    };
    const remeasure = () => { fanCards.forEach(c => { c._dx = null; c._dy = null; }); updateFan(); };
    state.fanRemeasure = remeasure;
    updateFan();
    extra.push(updateFan);
    on(window, "resize", remeasure);
  }

  $("[data-plan]").forEach(el => {
    const feat = el.hasAttribute("data-featured");
    el._baseRest = feat ? "translateY(-10px)" : "";
    const restShadow = feat ? "0 4px 20px rgba(182,130,53,.1)" : "none";
    const restT = () => fanRest.get(el) || el._baseRest;
    if (!fanRest.has(el)) el.style.transform = el._baseRest;
    on(el, "mouseenter", () => {
      el._hovering = true;
      el.style.transform = (fanRest.get(el) ? fanRest.get(el) + " " : "") + (feat ? "translateY(-18px)" : "translateY(-8px)");
      el.style.boxShadow = feat ? "0 18px 44px rgba(182,130,53,.22)" : "0 12px 32px rgba(45,43,43,.14)";
    });
    on(el, "mouseleave", () => { el._hovering = false; el.style.transform = restT(); el.style.boxShadow = restShadow; });
  });

  /* ---- plan tabs ---- */
  const tabs = $("[data-tab]"), panels = $("[data-panel]");
  tabs.forEach(t => on(t, "click", () => {
    tabs.forEach(o => {
      const active = o === t;
      o.style.background = active ? "var(--color-text)" : "transparent";
      o.style.color = active ? "var(--color-bg)" : "var(--color-text)";
    });
    panels.forEach(p => {
      const active = p.dataset.panel === t.dataset.tab;
      p.style.display = active ? "grid" : "none";
      if (!active) return;
      const show = () => { p.style.opacity = "1"; p.style.transform = "translateY(0)"; };
      if (reduce) { show(); return; }
      p.style.transition = "none";
      p.style.opacity = "0"; p.style.transform = "translateY(14px)";
      setTimeout(() => {
        p.style.transition = "opacity .6s ease, transform .6s cubic-bezier(.16,1,.3,1)";
        show();
      }, 30);
      setTimeout(show, 500);
    });
    if (state.fanRemeasure) setTimeout(state.fanRemeasure, 30);
  }));

  /* ---- mobile hamburger menu ---- */
  const menuBtn = root.querySelector("#menuBtn");
  const mobileMenu = root.querySelector("#mobileMenu");
  const menuLine1 = root.querySelector("#menuLine1");
  const menuLine2 = root.querySelector("#menuLine2");
  const menuLine3 = root.querySelector("#menuLine3");
  let menuOpen = false;
  const setMenuOpen = (open) => {
    menuOpen = open;
    if (mobileMenu) { mobileMenu.style.opacity = open ? "1" : "0"; mobileMenu.style.pointerEvents = open ? "auto" : "none"; }
    if (menuBtn) menuBtn.setAttribute("aria-expanded", open ? "true" : "false");
    if (menuLine1) menuLine1.style.transform = open ? "translateY(7px) rotate(45deg)" : "none";
    if (menuLine2) menuLine2.style.opacity = open ? "0" : "1";
    if (menuLine3) { menuLine3.style.transform = open ? "translateY(-7px) rotate(-45deg)" : "none"; menuLine3.style.width = open ? "100%" : "65%"; }
    document.body.style.overflow = open ? "hidden" : "";
  };
  state.closeMobileMenu = () => setMenuOpen(false);
  if (menuBtn) on(menuBtn, "click", () => setMenuOpen(!menuOpen));
  $("[data-mobilenav]").forEach(a => on(a, "click", () => setMenuOpen(false)));
  cleanup.push(() => { document.body.style.overflow = ""; });

  /* ---- language toggle ---- */
  const pt = {};
  $("[data-i18n]").forEach(el => { pt[el.dataset.i18n] = el.innerHTML; });
  const btn = root.querySelector("#lang");
  if (btn) on(btn, "click", () => {
    const toEn = lang === "pt";
    lang = toEn ? "en" : "pt";
    $("[data-i18n]").forEach(el => {
      const k = el.dataset.i18n;
      const v = toEn ? EN[k] : pt[k];
      if (v != null) el.innerHTML = v;
    });
    btn.innerHTML = toEn
      ? '<span style="opacity:.4">PT</span> / EN'
      : 'PT / <span style="opacity:.4">EN</span>';
    document.documentElement.lang = toEn ? "en" : "pt-BR";
    if (procSideDesc && procSideIdx >= 0) procSideDesc.textContent = procBenefits[lang][procSideIdx];
  });

  return () => cleanup.forEach(f => f());
}
